import {createHash} from 'node:crypto';
import {createRequire} from 'node:module';
import {fileURLToPath} from 'node:url';
import {createCanvasBackend} from '../../../lib/canvas/runtime-host.mjs';
const require=createRequire(import.meta.url),{chromium}=require('/Users/yubowen/.npm/_npx/e41f203b7505f1fb/node_modules/playwright');
const temp=await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(),'dsh-canvas-dialog-'))),pub=fileURLToPath(new URL('../public/',import.meta.url)),report={checks:[],requests:[],supplierRequests:0},backend=createCanvasBackend({rootDir:path.join(temp,'owned')});
const html=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"></head><body><button id="open">选择文件</button><button id="save">导出文本</button><button id="directory">选择目录</button><output id="result"></output><script type="module">import {bootstrap} from '/aiyoucodex-dsh/canvas/ui/host-shim.js';await bootstrap();for(const id of ['open','save','directory'])document.getElementById(id).onclick=async()=>{try{let value;if(id==='open')value=await __TAURI_INTERNALS__.invoke('plugin:dialog|open',{options:{multiple:true,filters:[{name:'JSON',extensions:['json']}]}});if(id==='directory')value=await __TAURI_INTERNALS__.invoke('plugin:dialog|open',{options:{directory:true}});if(id==='save'){value=await __TAURI_INTERNALS__.invoke('plugin:dialog|save',{options:{defaultPath:'actual-export.json',filters:[{extensions:['json']}]}});if(value)await __TAURI_INTERNALS__.invoke('write_text_file_atomic',{path:value,body:JSON.stringify({actual:'本机真实导出'})});}document.getElementById('result').textContent=JSON.stringify({value});}catch(error){document.getElementById('result').textContent=JSON.stringify({error:error.message});}};window.ready=true;</script></body></html>`;
const server=http.createServer(async(req,res)=>{try{const url=new URL(req.url,'http://127.0.0.1');if(url.pathname.endsWith('/rpc')){let raw='';for await(const c of req)raw+=c;const body=JSON.parse(raw);report.requests.push(body.command);if(/model_|resume|discover|catalog/.test(body.command))throw Error('No model operations allowed');let value;try{value={ok:true,value:await backend.invoke(body.command,body.args,{projectId:body.projectId,sessionId:body.sessionId})};}catch(error){value={ok:false,error:error.message};}res.setHeader('Content-Type','application/json');res.end(JSON.stringify(value));return;}if(url.pathname.endsWith('/file')){res.end(await fs.readFile(await backend.authorizeFile(url.searchParams.get('path'))));return;}if(url.pathname.endsWith('/host-shim.js')){res.setHeader('Content-Type','text/javascript');res.end(await fs.readFile(path.join(pub,'host-shim.js')));return;}res.setHeader('Content-Type','text/html');res.end(html);}catch(error){res.statusCode=500;res.end(error.message);}});await new Promise(r=>server.listen(0,'127.0.0.1',r));let browser;
try{browser=await chromium.launch({channel:'chrome',headless:true});const page=await browser.newPage();await page.goto(`http://127.0.0.1:${server.address().port}/?projectId=dialog-project&sessionId=fixture`);await page.waitForFunction(()=>window.ready);const first=path.join(temp,'one.json'),second=path.join(temp,'two.json');await fs.writeFile(first,'{"one":1}');await fs.writeFile(second,'{"two":2}');const picker=page.waitForEvent('filechooser');await page.locator('#open').click();await(await picker).setFiles([first,second]);await page.waitForFunction(()=>document.querySelector('#result').textContent.includes('browser-uploads'));const paths=JSON.parse(await page.locator('#result').textContent()).value;assert.equal(paths.length,2);assert.notEqual(paths[0],paths[1]);assert.deepEqual(await Promise.all(paths.map(p=>fs.readFile(p,'utf8'))),['{"one":1}','{"two":2}']);report.checks.push({id:'browser.real_file_input_multiple_staging',status:'pass',paths});await page.locator('#save').click();await page.locator('[data-dsh-save-dialog] input').fill('fixture-download.json');await page.locator('[data-dsh-save-dialog] button[type=submit]').click();const link=page.locator('[data-dsh-export-list] a').first();await link.waitFor();const event=page.waitForEvent('download');await link.click();const downloaded=await event,out=path.join(temp,'downloaded.json');await downloaded.saveAs(out);const bytes=await fs.readFile(out);assert.deepEqual(JSON.parse(bytes),{actual:'本机真实导出'});report.checks.push({id:'browser.real_save_dialog_write_and_download',status:'pass',downloadedPath:out,bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex')});await page.locator('#directory').click();await page.waitForFunction(()=>document.querySelector('#result').textContent.includes('不能选择本机目录'));report.checks.push({id:'browser.directory_selection_explicit_unsupported',status:'pass'});await page.screenshot({path:path.join(temp,'dialog.png')});report.pass=true;}catch(error){report.error=error.stack;process.exitCode=1;}finally{await browser?.close();await backend.dispose();server.closeAllConnections();await new Promise(r=>server.close(r));await fs.writeFile(path.join(temp,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({report:path.join(temp,'report.json'),pass:report.pass,error:report.error}));}
